inferred_model = validated.model

if filter_args:
    # Copy to avoid mutating the caller's sequence below.
    filter_args_ = list(filter_args)
else:
    # Handle classmethods and instance methods
    existing_params: list[str] = list(sig.parameters.keys())
    if existing_params and existing_params[0] in {"self", "cls"} and in_class:
        filter_args_ = [existing_params[0], *list(FILTERED_ARGS)]
    else:
        filter_args_ = list(FILTERED_ARGS)

# Exclude injected args from the schema regardless of whether `filter_args`
# was provided. Injected args (e.g. `InjectedToolArg`, `ToolRuntime`) are
# supplied at runtime rather than by the model, so they should not appear in
# the generated schema.
if not include_injected:
    for existing_param in sig.parameters:
        if (
            _is_injected_arg_type(sig.parameters[existing_param].annotation)
            and existing_param not in filter_args_
        ):
            filter_args_.append(existing_param)

description, arg_descriptions = _infer_arg_descriptions(
    func,
    parse_docstring=parse_docstring,
    error_on_invalid_docstring=error_on_invalid_docstring,
)

def _parse_google_docstring(
    docstring: str | None,
    args: list[str],
    *,
    error_on_invalid_docstring: bool = False,
) -> tuple[str, dict[str, str]]:
    """Parse the function and argument descriptions from the docstring of a function.

    Assumes the function docstring follows Google Python style guide.

    Args:
        docstring: The docstring to parse.
        args: The list of argument names to extract descriptions for.
        error_on_invalid_docstring: Whether to raise an error if the docstring is
            invalid.

    Returns:
        A tuple of the function description and a dictionary of argument descriptions.
    """
    if docstring:
        docstring_blocks = docstring.split("\n\n")
        if error_on_invalid_docstring:
            filtered_annotations = {
                arg
                for arg in args
                if arg not in {"run_manager", "callbacks", "runtime", "return"}
            }
            if filtered_annotations and (
                len(docstring_blocks) < _MIN_DOCSTRING_BLOCKS
                or not any(block.startswith("Args:") for block in docstring_blocks[1:])
            ):
                msg = "Found invalid Google-Style docstring."
                raise ValueError(msg)
        descriptors = []
        args_block = None
        past_descriptors = False
        for block in docstring_blocks:
            if block.startswith("Args:"):
                args_block = block
                break
            if block.startswith(("Returns:", "Example:")):
                # Don't break in case Args come after
                past_descriptors = True
            elif not past_descriptors:
                descriptors.append(block)
            else:
                continue
        description = " ".join(descriptors).strip()
    else:
        if error_on_invalid_docstring:
            msg = "Found invalid Google-Style docstring."
            raise ValueError(msg)
        description = ""
        args_block = None
    arg_descriptions: dict[str, str] = {}
